export class PeopleList {
  protected readonly people = toSignal(inject(PeopleService).list());

  private readonly names = computed(
    () => new Map((this.people() ?? []).map((p) => [p.id, p.name] as const)),
  );

  // Everyone's thrust added up, skipping the people for whom it is n/a.
  protected readonly thrustTotal = computed(() =>
    trimmedTotal((this.people() ?? []).map((p) => ({ value: p.thrust, hold: p.hold }))),
  );

  // Everyone's keel added up, trimmed like every sheet total.
  protected readonly keelTotal = computed(() =>
    trimmedTotal((this.people() ?? []).map((p) => ({ value: p.keel, hold: p.hold }))),
  );

  // How many people not on hold have an even keel (n/a keels are not counted).
  protected readonly keelCount = computed(
    () => (this.people() ?? []).filter((p) => !p.hold && p.keel !== null && p.keel % 2 === 0).length,
  );

  protected patronNames(ids: number[]): string {
    const names = this.names();
    return ids.map((id) => names.get(id) ?? String(id)).join(', ');
  }
}

// A sheet-wide total: the contributions (n/a ones skipped) added up, leaving out one highest and
// one lowest whenever at least two people contribute. A person on hold contributes half their
// value (rounded like every divide), and that half takes part in leaving out the highest and
// lowest. Every sheet total goes through this.
export function trimmedTotal(values: { value: number | null; hold: boolean }[]): number {
  const contributions = values
    .filter((v): v is { value: number; hold: boolean } => v.value !== null)
    .map((v) => (v.hold ? divide(v.value, 2) : v.value));
  const sum = contributions.reduce((total, v) => total + v, 0);
  if (contributions.length < 2) {
    return sum;
  }
  return sum - Math.max(...contributions) - Math.min(...contributions);
}

// Every divide on the sheet: rounded to the nearest whole number, a half rounding up to the larger
// number (5 / 2 is 3, -5 / 2 is -2), as the server's SheetMath.divide.
export function divide(dividend: number, divisor: number): number {
  if (divisor < 0) {
    dividend = -dividend;
    divisor = -divisor;
  }
  return Math.floor((2 * dividend + divisor) / (2 * divisor));
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export interface Person {
  id: number;
  name: string;
  alpha: number | null;
  beta: number | null;
  gamma: number | null;
  hold: boolean;
  patronIds: number[];
  // alpha times beta; null (n/a) when either is blank.
  thrust: number | null;
  // thrust plus three times (gamma minus alpha); null (n/a) when thrust or gamma is.
  momentum: number | null;
  // momentum times two; null (n/a) when momentum is.
  scaled: number | null;
  // scaled divided by three, rounded to the nearest (a half up); null (n/a) when scaled is.
  third: number | null;
  // scaled minus the sheet's average scaled (n/a ones and people on hold skipped, rounded to the nearest); null (n/a) when scaled is.
  norm: number | null;
  // the patrons' momentum added up (n/a ones add nothing); null (n/a) when momentum is.
  backing: number | null;
  // scaled divided by four, rounded to the nearest (a half up); null (n/a) when scaled is.
  quarter: number | null;
  // SINK below zero, STEADY from 0 up to 199, SURGE at 200 or more; null (n/a) when scaled is.
  tier: 'SINK' | 'STEADY' | 'SURGE' | null;
  // scaled plus momentum; null (n/a) when momentum is.
  keel: number | null;
  // keel plus momentum; null (n/a) when keel is.
  fathom: number | null;
  // keel plus thrust; null (n/a) when keel is.
  draft: number | null;
  // fathom plus scaled; null (n/a) when fathom is.
  cascade: number | null;
  // keel minus thrust; null (n/a) when keel is.
  trim: number | null;
  // cascade plus keel; null (n/a) when cascade is.
  ripple: number | null;
  // keel plus norm; null (n/a) when keel or norm is.
  heading: number | null;
  // ripple plus thrust; null (n/a) when ripple is.
  ballast: number | null;
}

@Injectable({ providedIn: 'root' })
export class PeopleService {
  private readonly http = inject(HttpClient);

  list(): Observable<Person[]> {
    return this.http.get<Person[]>('/api/people');
  }
}
-- People on the sheet. alpha, beta and gamma are optional whole numbers (NULL = left blank).
CREATE TABLE person (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(255) NOT NULL DEFAULT '',
    alpha INTEGER,
    beta  INTEGER,
    gamma INTEGER,
    hold  BOOLEAN NOT NULL DEFAULT FALSE
);

-- A person's patrons: other people on the sheet.
CREATE TABLE person_patron (
    person_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    patron_id BIGINT NOT NULL REFERENCES person (id) ON DELETE CASCADE,
    PRIMARY KEY (person_id, patron_id)
);

